function isPDF(file){return file.type==='application/pdf'||/\.pdf$/i.test(file.name)}
async function photoWorker(update){if(!window.Tesseract)await new Promise((resolve,reject)=>{let s=document.createElement('script');s.src='./vendor/ocr/tesseract.min.js';s.onload=resolve;s.onerror=reject;document.head.append(s)});return Tesseract.createWorker('eng',1,{workerPath:new URL('./vendor/ocr/worker.min.js',location.href).href,corePath:new URL('./vendor/ocr',location.href).href,langPath:new URL('./vendor/ocr',location.href).href,workerBlobURL:false,gzip:true,logger:p=>update(p.status+' '+Math.round((p.progress||0)*100)+'%')})}
function pdfPageText(items){let lines=[];for(let a of items){if(!a.str?.trim())continue;let x=a.transform[4],y=a.transform[5],line=lines.find(l=>Math.abs(l.y-y)<3);if(!line){line={y,items:[]};lines.push(line)}line.items.push({x,width:a.width||0,str:a.str})}lines.sort((a,b)=>b.y-a.y);for(let l of lines)l.items.sort((a,b)=>a.x-b.x);let leftHeader=null,rightHeader=null;for(let l of lines)for(let a of l.items){if(/^ingredients?\s*:?$/i.test(a.str.trim()))leftHeader={...a,y:l.y};if(/^(?:method|instructions|directions|preparation)\s*:?$/i.test(a.str.trim()))rightHeader={...a,y:l.y}}const join=xs=>xs.map(a=>a.str.trim()).join(' ').trim();if(leftHeader&&rightHeader&&rightHeader.x-leftHeader.x>120&&Math.abs(leftHeader.y-rightHeader.y)<50){let split=(leftHeader.x+leftHeader.width+rightHeader.x)/2,top=Math.max(leftHeader.y,rightHeader.y)+3,header=lines.filter(l=>l.y>top).map(l=>join(l.items)),body=lines.filter(l=>l.y<=top);return [...header,...body.map(l=>join(l.items.filter(a=>a.x<split))).filter(Boolean),...body.map(l=>join(l.items.filter(a=>a.x>=split))).filter(Boolean)].join('\n')}return lines.map(l=>join(l.items)).join('\n')}
async function readRecipeFiles(files,report){let fileIndex=0;const update=t=>report('File '+fileIndex+' of '+files.length+' · '+t);let worker=null,text='';const ocr=async image=>{worker??=await photoWorker(update);return (await worker.recognize(image,{tessedit_pageseg_mode:'3'},{text:true,blocks:true})).data.text};try{for(let file of files){fileIndex++;update('Reading '+file.name);if(file.size>25*1024*1024)throw Error('Choose a file smaller than 25 MB.');if(isPDF(file)){update('Reading PDF…');let lib=await import('./vendor/pdf/pdf.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf/pdf.worker.mjs',location.href).href;let loading=lib.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}),pdf=await loading.promise;try{if(pdf.numPages>30)throw Error('Choose a recipe PDF of 30 pages or fewer.');for(let n=1;n<=pdf.numPages;n++){update('Reading PDF page '+n+' of '+pdf.numPages);let page=await pdf.getPage(n),content=await page.getTextContent(),pageText=pdfPageText(content.items);if(pageText.trim().length<20){let viewport=page.getViewport({scale:2}),canvas=document.createElement('canvas');if(viewport.width*viewport.height>18000000)throw Error('PDF page is too large to read.');canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;pageText=await ocr(canvas)}text+=pageText+'\n';page.cleanup()}}finally{await loading.destroy()}}else{update('Preparing photo…');worker??=await photoWorker(update);text+=await readCookbookPhoto(worker,await readablePhoto(file),update)+'\n'}}return text}finally{if(worker)await worker.terminate()}}
async function extractedRecipe(text,fileName=''){let r=navigator.onLine?await api('import/text',{text}):parseTextOffline(text);if(/chefsteps/i.test(fileName))r.source=[r.source,'ChefSteps'].filter(Boolean).join(' · ');if(!r.source)r.source=fileName;return r}
async function readPhotos(){if(importBusy)return;let files=importPages.map(p=>p.file);if(!files.length)return toast('Add recipe photos or a PDF first.');importBusy=true;renderImportPages();try{$('importStatus').textContent='Reading '+files.length+' file(s) in order…';let text=await readRecipeFiles(files,t=>{if($('importStatus'))$('importStatus').textContent=t});let r=await extractedRecipe(text,files.map(f=>f.name).join(', '));r.reviewPhotoUrls=importPages.map(p=>p.preview).filter(Boolean);r.warnings??=[];r.warnings.unshift('Photo reading can confuse small fractions or curved text. Compare the originals and check amounts and method wording before saving.');if(files.length>1)r.warnings.unshift('Combined '+files.length+' files in the page order you selected. Check steps that continue across page breaks.');editRecipe(null,r)}catch(e){if($('importStatus'))$('importStatus').textContent='Unable to read the recipe pages: '+e.message}finally{importBusy=false;renderImportPages()}}
async function importRecipePDF(file){let form=$('dialogContent').querySelector('form'),existing=Object.fromEntries(new FormData(form));try{let text=await readRecipeFiles([file],t=>{if($('recipeFileStatus'))$('recipeFileStatus').textContent=t}),r=await extractedRecipe(text,file.name);r.source=existing.source?.trim()&&existing.source.trim()!=='My recipe'?existing.source.trim():r.source;r.rating=Number(existing.rating)||0;r.favorite=!!draft.favorite;r.photo=photo;r.id=draft.id;r.revision=draft.revision;editRecipe(r.id,r)}catch(e){if($('recipeFileStatus'))$('recipeFileStatus').textContent='Unable to read PDF: '+e.message}}
async function exportData(){let blob=new Blob([JSON.stringify({format:'Kitchen Notebook backup v1',exported:new Date().toISOString(),state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='kitchen-notebook-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}async function logout(){if(queue.length)return toast('Sync your saved changes before signing out.');try{await api('logout',{})}catch(e){return toast('Connect to sign out securely.')}state=null;user=null;queue=[];conflicts=[];await save();auth()}
async function demo(){try{if(queue.length)throw Error('Sync pending changes first.');let op={id:uid(),type:'demo',payload:{},at:new Date().toISOString()};state=await api('operation',{operation:op});await save();render()}catch(e){toast(e.message)}}
async function offlineReader(){try{$('offlineStatus').textContent='Saving photo reader files…';let cache=await caches.open('kitchen-drive-shell-v1');for(let name of ['tesseract.min.js','worker.min.js','tesseract-core-lstm.wasm.js','tesseract-core-simd-lstm.wasm.js','tesseract-core-relaxedsimd-lstm.wasm.js','eng.traineddata.gz'])await cache.add('./vendor/ocr/'+name);for(let path of ['./vendor/pdf/pdf.mjs','./vendor/pdf/pdf.worker.mjs','./vendor/heic/heic-to.js'])await cache.add(path);$('offlineStatus').textContent='Photo reader saved for offline use on this device.'}catch(e){$('offlineStatus').textContent='Unable to save the reader. Try again while connected.'}}
(async()=>{await storage();let cached=await get();if(cached){({state,user,queue,conflicts}=cached);conflicts??=[]}try{let current=await api('me');if(user&&current.household!==user.household){state=null;queue=[];conflicts=[]}user=current;if(!state)state=await api('state');await save()}catch(e){}render();if(user)sync();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');window.addEventListener('online',sync);setInterval(()=>{if(!modal.open)sync()},30000)})();

function removePantry(id){if(confirm('Remove all '+item(id).name+' stock, including unmeasured packages?'))act('removeStock',{ingredientId:id,expected:state.pantry[id]||0})}

let pendingBackup=null;
async function previewBackup(file){
 if(!file)return;
 try{
  if(file.size>50_000_000)throw new Error('Choose a backup smaller than 50 MB.');
  if(queue.length||conflicts.length||syncing)throw new Error('Finish syncing and review any conflicts before importing.');
  pendingBackup=null;
  let backup=JSON.parse(await file.text()),current=await api('state');
  let payload={backup,expectedVersion:current.version},summary=await api('import/backup/preview',payload);
  pendingBackup={...payload,summary};
  $('backupPreview').innerHTML=backupPreviewMarkup();
 }catch(e){toast(e.message);if($('backupPreview'))$('backupPreview').textContent='';}
}
function backupPreviewMarkup(){
 if(!pendingBackup)return '';
 let summary=pendingBackup.summary;
 return `<div class="notice"><h3>Ready to import</h3><p>${summary.recipes} recipes · ${summary.pantryItems} pantry items · ${summary.dinners} dinners · ${summary.groceries} pending groceries · ${summary.purchased} purchased groceries.</p><p>Recipe photos, ratings, favourites and purchase history will move with your records. Your login stays the same.</p><button onclick="importBackup()">Import into this empty household</button><button onclick="pendingBackup=null;document.getElementById('backupPreview').innerHTML=''">Cancel</button></div>`;
}
async function importBackup(){
 if(!pendingBackup)return;
 try{
  if(queue.length||conflicts.length||syncing)throw new Error('Finish syncing before importing.');
  state=await api('import/backup',pendingBackup);pendingBackup=null;await save();render();toast('Household backup imported.');
 }catch(e){toast(e.message);}
}

function auth(){return driveAuth()}
function household(){return driveHousehold()}
